type Cache struct {
    mu   sync.Mutex
    data map[string]string
}

func (c Cache) Get(k string) string {   // получатель-значение: мьютекс скопирован!
    c.mu.Lock()                          // блокируем копию — защиты нет
    defer c.mu.Unlock()
    return c.data[k]
}
// go vet: Get passes lock by value: Cache contains sync.Mutex

type Server struct {
    addr    string
    timeout time.Duration
}

type Option func(*Server)

func WithTimeout(d time.Duration) Option { return func(s *Server) { s.timeout = d } }

func NewServer(addr string, opts ...Option) *Server {
    s := &Server{addr: addr, timeout: 30 * time.Second}
    for _, opt := range opts {
        opt(s)
    }
    return s
}

srv := NewServer(":8080", WithTimeout(5*time.Second))
